<?php
defined('ABSPATH') || exit;

function sanro_dm_svg_escape($value) { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_XML1,'UTF-8'); }
function sanro_dm_svg_number($value,$default=0) { if(!is_numeric($value))return $default;$number=(float)$value;if(!is_finite($number)||abs($number)>10000)return false;return rtrim(rtrim(number_format($number,4,'.',''),'0'),'.')?:'0'; }
function sanro_dm_svg_color($value) {
    if(!is_string($value))return false;$value=trim($value);if(in_array(strtolower($value),array('transparent','none'),true))return 'none';
    if(preg_match('/^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i',$value))return strtolower($value);
    if(preg_match('/^rgba?\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})(?:\s*,\s*(0|1|0?\.\d+))?\s*\)$/i',$value,$m)) {foreach(array(1,2,3) as $i)if((int)$m[$i]>255)return false;$hex=sprintf('#%02x%02x%02x',(int)$m[1],(int)$m[2],(int)$m[3]);return array($hex,isset($m[4])?(float)$m[4]:1);}
    return false;
}
function sanro_dm_svg_asset_data($assetId,$ownerId,$budget) {
    global $wpdb;$t=sanro_dm_tables();$asset=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['assets']} WHERE id=%s AND user_id=%d",sanitize_text_field($assetId),(int)$ownerId));if(!$asset)return new WP_Error('invalid_master_asset','A private image is missing or belongs to another account.',array('status'=>400));
    $root=sanro_dm_private_root();if(is_wp_error($root))return $root;$path=realpath($root.'/'.$asset->path);if(!$path||strpos($path,$root.DIRECTORY_SEPARATOR)!==0||!is_file($path)||filesize($path)>8*MB_IN_BYTES||$budget+filesize($path)>32*MB_IN_BYTES)return new WP_Error('invalid_master_asset','Private image exceeds the render budget.',array('status'=>413));
    $mime=$asset->mime;if(!in_array($mime,array('image/png','image/jpeg','image/webp'),true))return new WP_Error('invalid_master_asset','Unsupported private image type.',array('status'=>400));return array('mime'=>$mime,'data'=>base64_encode(file_get_contents($path)),'bytes'=>filesize($path));
}
function sanro_dm_svg_local_font($family,&$budget) {
    $fonts=(array)get_option('sanro_dm_fonts',array());$path=false;$mime='font/woff2';
    if(!empty($fonts[$family]['file'])){$file=$fonts[$family]['file'];if(basename($file)!==$file||pathinfo($file,PATHINFO_EXTENSION)!=='woff2')return false;$uploads=wp_upload_dir();$dir=realpath(trailingslashit($uploads['basedir']).'sanro-design-maker-fonts');$path=$dir?realpath($dir.'/'.$file):false;if(!$path||strpos($path,$dir.DIRECTORY_SEPARATOR)!==0||file_get_contents($path,false,null,0,4)!=='wOF2')return false;}
    elseif($family==='Anton'){$path=realpath(__DIR__.'/../assets/fonts/Anton-Regular.ttf');$mime='font/ttf';if(!$path||file_get_contents($path,false,null,0,4)!=="\x00\x01\x00\x00")return false;}
    if(!$path||!is_file($path)||filesize($path)>3*MB_IN_BYTES||$budget+filesize($path)>8*MB_IN_BYTES)return false;$bytes=filesize($path);$budget+=$bytes;return array('mime'=>$mime,'data'=>base64_encode(file_get_contents($path)));
}
function sanro_dm_design_to_svg($design,$ownerId) {
    if(!is_array($design)||empty($design['objects'])||!is_array($design['objects'])||count($design['objects'])>250)return new WP_Error('invalid_render_design','Design cannot be rendered.',array('status'=>400));$svg=array('<?xml version="1.0" encoding="UTF-8"?>','<svg xmlns="http://www.w3.org/2000/svg" width="4000" height="4000" viewBox="0 0 1000 1000">');$budget=0;
    $fontDefs=array();foreach($design['objects'] as $o){if(!isset($o['fontFamily'])||!in_array($o['type']??'',array('textbox','i-text','text','IText','Textbox'),true))continue;$family=sanitize_text_field($o['fontFamily']);if(!in_array($family,sanro_dm_font_families(),true)||isset($fontDefs[$family]))continue;$fontData=sanro_dm_svg_local_font($family,$budget);if($fontData)$fontDefs[$family]='<style>@font-face{font-family:"'.sanro_dm_svg_escape($family).'";src:url(data:'.$fontData['mime'].';base64,'.$fontData['data'].') format("'.($fontData['mime']==='font/ttf'?'truetype':'woff2').'");font-weight:100 900;}</style>';}
    if($fontDefs)$svg[]='<defs>'.implode('',$fontDefs).'</defs>';
    foreach($design['objects'] as $object){if(!is_array($object)||empty($object['type']))return new WP_Error('invalid_render_object','Design contains an unsupported object.',array('status'=>400));$type=strtolower((string)$object['type']);$left=sanro_dm_svg_number($object['left']??0);$top=sanro_dm_svg_number($object['top']??0);$sx=sanro_dm_svg_number($object['scaleX']??1);$sy=sanro_dm_svg_number($object['scaleY']??1);$angle=sanro_dm_svg_number($object['angle']??0);$opacity=sanro_dm_svg_number($object['opacity']??1);$w=sanro_dm_svg_number($object['width']??0);$h=sanro_dm_svg_number($object['height']??0);
        if(in_array(false,array($left,$top,$sx,$sy,$angle,$opacity,$w,$h),true)||(float)$w<0||(float)$h<0||abs((float)$sx)>20||abs((float)$sy)>20||(float)$opacity<0||(float)$opacity>1)return new WP_Error('invalid_render_transform','Design contains an invalid transform.',array('status'=>400));
        $fill=sanro_dm_svg_color($object['fill']??'none');$stroke=sanro_dm_svg_color($object['stroke']??'none');if($fill===false||$stroke===false)return new WP_Error('invalid_render_color','Only solid safe colors are supported by the private renderer.',array('status'=>400));$fillColor=is_array($fill)?$fill[0]:$fill;$strokeColor=is_array($stroke)?$stroke[0]:$stroke;$fillAlpha=is_array($fill)?$fill[1]:1;$strokeAlpha=is_array($stroke)?$stroke[1]:1;$strokeWidth=sanro_dm_svg_number($object['strokeWidth']??0);if($strokeWidth===false||$strokeWidth<0||$strokeWidth>100)return new WP_Error('invalid_render_stroke','Invalid stroke width.',array('status'=>400));
        $flipX=!empty($object['flipX'])?-1:1;$flipY=!empty($object['flipY'])?-1:1;$transform='translate('.$left.' '.$top.') rotate('.$angle.' '.((float)$w/2).' '.((float)$h/2).') scale('.((float)$sx*$flipX).' '.((float)$sy*$flipY).')';$style='fill="'.sanro_dm_svg_escape($fillColor).'" fill-opacity="'.$fillAlpha.'" stroke="'.sanro_dm_svg_escape($strokeColor).'" stroke-opacity="'.$strokeAlpha.'" stroke-width="'.$strokeWidth.'" opacity="'.$opacity.'"';
        if($type==='rect')$svg[]='<rect x="0" y="0" width="'.$w.'" height="'.$h.'" rx="'.sanro_dm_svg_escape(sanro_dm_svg_number($object['rx']??0)).'" '.$style.' transform="'.$transform.'"/>';
        elseif($type==='circle'){$r=sanro_dm_svg_number($object['radius']??0);if($r===false||$r<0||$r>10000)return new WP_Error('invalid_render_object','Invalid circle radius.',array('status'=>400));$svg[]='<circle cx="'.$r.'" cy="'.$r.'" r="'.$r.'" '.$style.' transform="'.$transform.'"/>';}
        elseif($type==='triangle')$svg[]='<polygon points="0,'.$h.' '.((float)$w/2).',0 '.$w.','.$h.'" '.$style.' transform="'.$transform.'"/>';
        elseif($type==='line'){$x1=sanro_dm_svg_number((float)($object['x1']??0)-(float)$left);$y1=sanro_dm_svg_number((float)($object['y1']??0)-(float)$top);$x2=sanro_dm_svg_number((float)($object['x2']??0)-(float)$left);$y2=sanro_dm_svg_number((float)($object['y2']??0)-(float)$top);if(in_array(false,array($x1,$y1,$x2,$y2),true))return new WP_Error('invalid_render_object','Invalid line coordinates.',array('status'=>400));$svg[]='<line x1="'.$x1.'" y1="'.$y1.'" x2="'.$x2.'" y2="'.$y2.'" stroke="'.sanro_dm_svg_escape($strokeColor==='none'?$fillColor:$strokeColor).'" stroke-width="'.$strokeWidth.'" opacity="'.$opacity.'" transform="'.$transform.'"/>';}
        elseif(in_array($type,array('text','i-text','itext','textbox'),true)){$text=(string)($object['text']??'');if(strlen($text)>10000)return new WP_Error('invalid_render_text','Text object is too long.',array('status'=>400));$font=sanitize_text_field($object['fontFamily']??'Arial');if(!in_array($font,array_merge(array('Arial','sans-serif','serif'),sanro_dm_font_families()),true))$font='Arial';$fontSize=sanro_dm_svg_number($object['fontSize']??40);if($fontSize===false||$fontSize<1||$fontSize>1000)return new WP_Error('invalid_render_text','Invalid font size.',array('status'=>400));$weight=isset($object['fontWeight'])&&in_array((string)$object['fontWeight'],array('bold','700','800','900'),true)?'700':'400';$align=$object['textAlign']??'left';$anchor=$align==='center'?'middle':($align==='right'?'end':'start');$x=$align==='center'?((float)$w/2):($align==='right'?(float)$w:0);$lines=explode("\n",$text);$svg[]='<text x="'.$x.'" y="'.$fontSize.'" fill="'.sanro_dm_svg_escape($fillColor==='none'?'#000000':$fillColor).'" stroke="'.sanro_dm_svg_escape($strokeColor).'" stroke-width="'.$strokeWidth.'" opacity="'.$opacity.'" font-family="'.sanro_dm_svg_escape($font).'" font-size="'.$fontSize.'" font-weight="'.$weight.'" text-anchor="'.$anchor.'" transform="'.$transform.'">';foreach($lines as $index=>$line)$svg[]='<tspan x="'.$x.'" dy="'.($index===0?'0':$fontSize*1.2).'">'.sanro_dm_svg_escape($line).'</tspan>';$svg[]='</text>';}
        elseif($type==='image'){$assetId=$object['data']['assetId']??'';if(!$assetId)return new WP_Error('invalid_render_asset','Images must be private uploaded assets.',array('status'=>400));$asset=sanro_dm_svg_asset_data($assetId,$ownerId,$budget);if(is_wp_error($asset))return $asset;$budget+=$asset['bytes'];$svg[]='<image x="0" y="0" width="'.$w.'" height="'.$h.'" href="data:'.$asset['mime'].';base64,'.$asset['data'].'" preserveAspectRatio="none" transform="'.$transform.'" opacity="'.$opacity.'"/>';
        }else return new WP_Error('invalid_render_object','Design contains an unsupported object type.',array('status'=>400));
    }
    $svg[]='</svg>';$result=implode("\n",$svg);if(strlen($result)>40*MB_IN_BYTES)return new WP_Error('render_too_large','Private vector master exceeds its size limit.',array('status'=>413));return $result;
}
function sanro_dm_render_design(WP_REST_Request $request) {
    global $wpdb;$uid=get_current_user_id();$rate=sanro_dm_rate_limit($uid,'render',20);if(is_wp_error($rate))return $rate;$id=sanitize_text_field($request['id']);$t=sanro_dm_tables();$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['designs']} WHERE id=%s AND user_id=%d",$id,$uid));if(!$row)return new WP_Error('not_found','Design not found.',array('status'=>404));$svg=sanro_dm_design_to_svg(json_decode($row->design,true),$uid);if(is_wp_error($svg))return $svg;$root=sanro_dm_private_root();if(is_wp_error($root))return $root;$hash=hash('sha256',$svg);$masterId=sanro_dm_uuid();$relative='masters/'.$uid.'/'.$masterId.'.svg';$path=$root.'/'.$relative;if(!wp_mkdir_p(dirname($path))||file_put_contents($path,$svg,LOCK_EX)===false)return new WP_Error('render_storage_failed','Private master could not be stored.',array('status'=>500));@chmod($path,0600);
    $old=$wpdb->get_row($wpdb->prepare("SELECT id,path FROM {$t['masters']} WHERE design_id=%s AND user_id=%d",$id,$uid));if($old){$oldPath=realpath($root.'/'.$old->path);if($oldPath&&strpos($oldPath,$root.DIRECTORY_SEPARATOR)===0&&is_file($oldPath))@unlink($oldPath);$wpdb->delete($t['masters'],array('id'=>$old->id),array('%s'));}
    if(!$wpdb->insert($t['masters'],array('id'=>$masterId,'design_id'=>$id,'user_id'=>$uid,'path'=>$relative,'sha256'=>$hash,'bytes'=>strlen($svg),'created_at'=>current_time('mysql',true)),array('%s','%s','%d','%s','%s','%d','%s'))){@unlink($path);return new WP_Error('render_index_failed','Private master metadata could not be saved.',array('status'=>500));}return new WP_REST_Response(array('master_id'=>$masterId,'format'=>'svg','sha256'=>$hash,'bytes'=>strlen($svg),'private'=>true),201);
}
function sanro_dm_cleanup_design_privates($designId,$ownerId) {
    global $wpdb;$t=sanro_dm_tables();$master=$wpdb->get_row($wpdb->prepare("SELECT id,path FROM {$t['masters']} WHERE design_id=%s AND user_id=%d",$designId,$ownerId));if($master){$root=sanro_dm_private_root();if(!is_wp_error($root)){$path=realpath($root.'/'.$master->path);if($path&&strpos($path,$root.DIRECTORY_SEPARATOR)===0&&is_file($path))@unlink($path);}$wpdb->delete($t['masters'],array('id'=>$master->id),array('%s'));}$wpdb->delete($t['shares'],array('design_id'=>$designId,'user_id'=>$ownerId),array('%s','%d'));
}
function sanro_dm_register_render_routes() {register_rest_route('sanro-design-maker/v1','/designs/(?P<id>[a-f0-9-]+)/render',array('methods'=>'POST','callback'=>'sanro_dm_render_design','permission_callback'=>'sanro_dm_storage_auth'));}
